"""Apply the reviewed v2 → v3 editorial changes once; history/v2 is immutable input."""
from pathlib import Path
import re,json
OUT=Path(__file__).resolve().parents[2]
OLD=Path('/Users/m5/.local/share/inresearch.ai/geluoke-research/2026-10-09-us-datacenter-power/history/v2/article.md')
paras=[p for p in OLD.read_text().strip().split('\n\n') if not p.startswith('![') and not re.match(r'^图\d+｜',p)]
def find(prefix):
 matches=[i for i,p in enumerate(paras) if p.startswith(prefix)]
 assert len(matches)==1,(prefix,matches)
 return matches[0]
def change(prefix,text):paras[find(prefix)]=text
def remove(prefix):paras.pop(find(prefix))
def after(prefix,text):paras.insert(find(prefix)+1,text)
def move(prefix,target):
 p=paras.pop(find(prefix));after(target,p)
change('这些变化说明，','电力正在改变美国数据中心的扩张方式。服务器、土地和客户合同备齐了，园区仍可能等待一座变电站；签下长期核电，也要继续安排输送和备用。用电在增长，但增长落在哪儿、哪些申请会兑现、供电能否按期到达，决定了下一座机房建在哪儿、什么时候开业。要理解这场变化，先从美国的电力地图看起。[4][5][13]')
change('谈美国数据中心用电，','美国本土连续的四十八个州，主要分属东部互联、西部互联和得州的ERCOT互联三大电力系统。每个系统内部的交流电网同步运行，三者之间没有全国统一的同步网络。东、西两大系统还连接加拿大部分电网；ERCOT覆盖得州大部分地区，州内西端、北部和东部另有其他互联覆盖。阿拉斯加和夏威夷不在这张本土地图里。[1][6]')
change('这三大系统之间有有限的直流联络，','图上的州界，并不是电力系统的全部边界。不同颜色之间有有限的直流联络，可以交换电力，但交换规模受设备容量与运行条件约束。西部有富余电，不能据此认定东部某个园区就能及时用上；得州大部分地区也不能像同一张交流电网内部那样，直接参与东西部的同步调度。[1][6]')
change('不过，三大电网不是全部问题。','地图回答了电在什么系统内流动，接下来还要找清楚谁管调度、谁负责送到客户门口。物理互联之下有区域市场与调度体系，再往下是具体电力公司的服务区。数据中心的签约供电方、区域调度机构和资产所有者，可能是不同主体。[1][2]')
change('美国常说的七家RTO/ISO，','美国常说的七家RTO/ISO，是PJM、MISO、SPP、CAISO、NYISO、ISO-NE和ERCOT。它们组织区域输电调度或批发市场，各自的职责和覆盖范围不同。七家机构并不是七家包办发电、输电、配电与零售的垂直垄断电力公司，也没有覆盖全美国所有地区。FERC在2026年6月针对其管辖的六家推出大负荷改革要求，ERCOT不在这组六家之中。[2]')
change('区域调度与批发市场的作用，','区域调度把发电资源、输电约束与用电需求放进共同规则，协调系统运行；地方电力公司则要落实客户接入：扩哪座变电站、修哪条线路、何时送电、采用什么费率。园区即使找到愿意卖电的发电商，这些工作也仍要完成。图中三层关系，分别对应全国系统、区域协调和客户交付，不能用一份购电合同把它们一并解决。[1][2]')
change('电力公司数量多，','电力公司多，也不意味着每个地方都有许多家公司争夺同一个客户。投资者所有的公用事业、市政公用事业、合作社、独立发电商和零售供电商，承担不同角色。地方网络通常有服务范围，零售选择权随地区制度变化。能换售电合同，未必能换掉送到园区的那条线路。[1][2]')
change('这一结构有历史来源，','这套分工有长期的法律与制度来源。1935年对《联邦电力法》的修订，奠定了联邦监管跨州输电与电力批发的重要法律基础。同年出台的《公用事业控股公司法》，重点处理公用事业控股公司的组织与监管。两部法律不能混作一部；地方零售和公用事业监管，通常仍保留重要的州级权限。[1][2]')
change('跨州输电线路确实会碰到多层审批：','建跨州线路，要协调路线、土地、环境、各州选址规则，以及涉及联邦土地等条件下的联邦手续。土地所有者和社会团体也可以通过土地权利、公众参与或诉讼影响项目。各方的权利和程序不同，协调成本却会共同落到工期上。联邦促进输电和特定条件下介入选址的机制，仍要在这套现实框架中推进。[3]')
change('对于数据中心来说，这些制度差异','对园区而言，这些制度最终要变成具体的交付承诺：由哪家电力公司供电，接到哪座变电站，扩建哪些线路，费用怎样回收，容量何时分期释放。国家层面的政策改变方向，服务区内的合同与工程决定开业日期。开发商需要把电力地图继续放大，一直看到供电服务区和接入点。[5][8]')
change('美国的数据中心也没有均匀地铺','数据中心并没有均匀铺在这张地图上。弗吉尼亚州议会联合审计与审查委员会JLARC在2024年的研究中，把北弗吉尼亚列为全球最大的成熟数据中心市场之一。网络连接、客户、配套服务和建设经验，让企业愿意继续聚集；新增电力需求也因此持续压向同一地区。[7]')
change('成熟集群还有存量与增量的差别。','集群内部，已有机房和新园区的处境也不同。已经接入的设施拥有现成供电条件，隔街新建的园区却可能触发新的网络投资。买下一座带供电合同的机房，与买地重新申请接入，资产价值不同；评估时要查合同权利能否转移、扩容能否获批，以及现有容量是否适合新的设备密度。[7][8]')
remove('这些差别最终都要写进园区的供电安排。')
change('美国数据中心的用电增长已经越过了可以忽略的阶段。','全国层面，用电增长已经相当明显。伯克利国家实验室LBNL在2024年发布的研究估算：美国数据中心2023年用电176TWh，占总用电量约4.4%；2014年为58TWh。十年间的变化，已经足以让电力规划把数据中心当作重要负荷。这套估算覆盖数据中心整体，包含AI以外的用途，采用研究模型，并非逐座机房电表的直接汇总。[3][4]')
change('同一报告把2028年的美国数据中心','同一报告预测，2028年美国数据中心全年用电可能达到325—580TWh，占美国总用电量约6.7%—12%。预测在2024年提出，区间宽度来自设备数量、使用率、AI需求与设施效率的不同假设。芯片功率提高会推动增长，新增设备装了多少、每年运行多久，同样影响最终电量。[3][4]')
change('这组全国数字解释了为什么电力行业','全国数字交代了行业方向，园区送电仍要看功率、地点与时间。TWh表示一段时期的电量，MW或GW表示功率。额定功率一样，全年稳定运行和只运行少数时段，消耗的电量不同；电网还要考虑这些负荷会不会同时出现在系统高峰。[1][4]')
change('一家数据中心可以听到三种都叫','园区等电，可能等在三处。第一处是发电：区域在关键时段有没有足够可靠的资源。第二处是输电：电源有了，通道能否把电送进负荷区。第三处是接入：上游条件具备，园区所需的线路、变电站和设备是否完成。图中沿着电厂、线路和变电设施看过去，就能看到这三种约束；它们需要不同的工程，购电合同无法代替最后一段线路。[1][7][14]')
change('北弗吉尼亚的典型矛盾，','北弗吉尼亚卡在成熟集群继续增长与系统扩建之间。JLARC的研究讨论了新增发电、输电、审批和居民成本等约束。网络与客户优势吸引企业继续聚集，新增容量便更依赖地区系统扩建。靠近已经运营的机房，有连接优势，却不保证新园区获得相同的供电条件。[7]')
change('把目光放到得州，','得州面对另一组条件。ERCOT主要互联系统独立运行，大负荷接入要结合本区域资源与安全要求。2026年6月启动的共同批次研究，试图把多个大项目放在一起评估；现场自供电和可中断服务，也成为协调新增负荷的路径。地区差异体现在资源、工程和服务规则上。[6]')
after('得州面对另一组条件。','四个案例放到地图上，位置与办法就更清楚了。北弗吉尼亚需要追上集群增长的扩建；得州调整共同接入研究；俄亥俄州既设定最低容量付款，也批准部分项目部署现场燃料电池；佐治亚州则把长期合同、扩建责任与灵活需求承诺放在一起。这些办法处理的是不同环节，费用与供电路线将在后文展开。[6][7][9][17][18]')
change('一座算力园区因此有几只同时走动的钟：','园区开业要让几张进度表对上：客户进场、服务器到货、机房完工、电力送达。服务器先到而送电延期，会占用资金；电力设施先建成、客户却迟迟不上线，又会留下利用不足的资产。各方需要约定负荷分期和建设里程碑，把承诺变成可以共同执行的排期。[5][8]')
remove('地区瓶颈也不是单纯的市场价格问题。')
change('美国数据中心眼前的电力瓶颈，','美国数据中心眼前的电力瓶颈，要同时看地点与工期。增加发电改善资源供应，扩跨区通道扩大互济，地方工程把电送进园区。项目在哪一层等待，就要补哪一层条件。这个判断也会改变对“需求很大”的理解：需要扩建多少设施，取决于有多少需求能够按时兑现。')
change('电网接到一份大容量申请，','一份容量申请，还不是电表上的负荷。申请时，开发商可能尚未确定全部客户；企业也可能同时比较多个地点。融资、供电报价和设备采购，都会改变规模与分期。规划部门要为增长留空间，也要识别哪些项目已经作出足够承诺，否则可能为尚未形成的需求提前建设过多资产。[5][14]')
change('项目真实性应当沿建设过程看。','看项目是否会兑现，可以沿着图中的证据走：地点与容量意向，系统研究，具有约束力的合同，建设与调试，送电及实际运行。每一步回答不同问题。土地协议证明取得开发条件，购电协议证明安排了交易；到了送电和持续负荷，才看见真正进入电力系统的需求。各地流程名称和先后可能不同，证据仍需要分别登记。[5][6]')
change('这项改革涉及75MW及以上、','ERCOT这项改革面向75MW及以上、满足资格条件的大负荷，并提供现场自供电或可中断负荷等路径。它在2026年6月公布的安排，把首批最终输电计划预计完成时间放在2027年秋季。计划形成以后，还要建设和投运。PJM的预测折减与ERCOT的共同研究虽是两种办法，却都在让申请者交代承诺程度和交付条件。[5][6]')
change('近期确定负荷与远期意向，','真实用电增长与项目兑现困难，正在同时发生。近期有明确承诺的负荷，可以推动具体投资；远期意向则要留在带条件的预测中。下一轮增长，要看有多少项目从申请走到工程，再进入持续运行的业务。电网要求的承诺越具体，扩建费用由谁承担的问题也越难回避。[4][5][6]')
change('另一项规定要求适用的大型客户','适用的大型客户，每月还要至少承担为其服务所发生的85%输电与配电成本，不论实际用电多少；2016年1月1日前已经开始服务的客户有豁免条件。这项最低付款锁定的是网络成本。按实际消耗结算的电能，属于账单中的另一部分。[8]')
move('成本分担还有一个必须保留的反例：','从企业账上看，')
change('成本分担还有一个必须保留的反例：','JLARC的研究提供了一个有用的对照：2024年委托的独立研究认为，当时费率总体上已经把现有服务成本适当地分配给包括数据中心在内的客户，同时担心未来增长提高全系统成本。现有客户承担了自己的服务成本，新增需求仍可能需要更贵的资源和网络投资。讨论居民是否受影响，要同时查看这两笔账。[7]')
change('俄亥俄州也有类似方向，','俄亥俄州的条款，锁定的是另一种费用。州消费者法律代表机构介绍，PUCO于2025年7月9日通过的AEP Ohio数据中心费率，要求新的大型数据中心对约定电力容量承担至少85%的付款义务，期限最长十二年。该机构页面还记载，行业团体在2025年11月提出上诉。与弗吉尼亚相比，数字相同，收费基数不同：一边是输配电成本，一边是合同容量相关付款。[17]')
change('居民成本确实存在压力，','居民会不会因此多付电费，各地研究的答案取决于情景。JLARC在2024年估计，到2040年，典型Dominion居民客户与发电、输电有关的月成本，可能增加14—37美元，以不变价计算。这是长期模型结果，地区和成本范围都有明确边界；图中保留这些条件，才能看懂它讨论的是哪一笔未来支出。[7]')
change('同一时期，也有电力公司主张','Georgia Power则预计，大客户的新增收入能够帮助分摊系统成本。它在2026年8月介绍获批的OpenAI合同及大负荷客户组合时，预测从2029年起每年可带来约9.5亿美元的客户节省。预测针对大负荷组合，采用公司测算，节省能否兑现取决于收入和成本进展。这与JLARC居民单户月成本模型，单位、期间和对象均不同。[9]')
remove('弗吉尼亚与佐治亚给出不同结果，')
change('当接入电网变慢，','接入变慢，企业会寻找新的电源与采购安排。先看这条路线补在哪里：签长期购电协议，可以安排电能、价格或环境属性；新电源、园区接入和紧张时段的可靠供电，则要有各自的工程与服务条件。核电、现场燃气和风光储，解决的问题并不相同。[11][13]')
change('核电受欢迎，','核电能够提供较稳定的低碳电能，适合长期运行的负荷。具体项目仍要分三种看：向既有电厂购电，支持停运机组重启，建设新反应堆。第一种调整售电安排，后两种有机会增加供给，但时间与工程要求不同。下面两个已经披露的案例，正好展示这种差别。[10][11][13]')
remove('这种路线的优势，是可以利用既有场址、')
change('Talen与Amazon的交易，','Talen与Amazon的安排，则来自既有核电厂。Talen在2025年6月披露，扩大的购电合同在全合同规模下达到1920MW，期限至2042年，并有延长选择。材料说明，园区建立电网连接后转向表前零售安排，过渡期保留部分表后安排。图中把它与Crane分开：前者是已有电厂的电能与容量交易，后者是推动停运机组重启，不能把合同MW当成新增机组装机。[11]')
change('现场燃气发电是另一条受到关注的路线。','现场燃气供电，把一部分资源建设移到园区附近。AEP在2025年6月披露，俄亥俄州批准在两个数据中心地点部署现场发电资源。获得批准，说明项目跨过了一项建设条件；运行还要等待施工、测试和其他必要准备。[18]')
change('这个俄亥俄州案例采用的是Bloom','这两个项目采用Bloom固体氧化物燃料电池，AWS和Cologix按长期协议承担全部成本。图中天然气经过处理，进入燃料电池，通过电化学反应产生直流电，再经过电力转换供给负荷。这条路线与燃气轮机或内燃机的机械发电不同，设备、交付与维护也需要分别看。共同要求是燃料可靠送达、现场设施按期建成，以及供电与备用安排适合业务。[3][18]')
change('天然气本身也不是没有网络依赖的能源。','现场发电仍依赖燃料网络。机器到位以后，天然气还要通过管道和合同持续到达；冬季紧张时，电力与燃气系统可能同时承压。NERC把两者协调列为可靠性工作的重要部分。改变电力接入路径，也意味着园区接手燃料供给、现场运行和维护的新责任。[14]')
change('这类整合的意义，','这类整合把电源、土地、接入和机房的开发时间表，放进更靠近的组织中。电源先建成、园区未准备好，或者园区完工、资源尚未到位，都会占用资本。科技企业可以减少部分协调成本，也会承担更多能源工程和投资风险；所在区域的电力系统规则仍然适用。[12][13]')
remove('小型模块化反应堆等新技术，')
change('电网供电仍然有很强的经济价值：','公共电网共享多种电源与备用，独立园区则需要自己组织相应能力，这也是网络供电仍有经济价值的原因。现场发电、核电PPA、风光和储能可以组合使用。选方案时先识别缺口：缺年度电量、接入能力、关键时段容量，还是交付时间，再比较投资、服务与可靠性。具体供电条件清楚了，选址才有可以落进账本的依据。[13]')
change('当电力成为项目时间表的关键条件，','电力成为时间表上的关键条件，选址排序也会改变。成熟市场的网络、客户与配套继续吸引企业；供电是否可靠、扩建是否明确、合同成本是否可控，则获得更高权重。企业需要比较的是整座园区能在哪一年营业，而不只是地址是否属于知名集群。[7][13]')
